// 1. Pega a hora e minutos exatos no fuso horário do Brasil (UTC-3)
const timeString = new Date().toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour12: false });
const [h, m] = timeString.split(':').map(Number);
const horaAtual = h + (m / 60);

// 2. Quadro de horários (Escala TVR)
const escala = [
  { email: 'member01@example.com', inicio: 18.0, fim: 23.0 },
  { email: 'member02@example.com', inicio: 6.0, fim: 15.0 },
  { email: 'member03@example.com', inicio: 7.0, fim: 17.0 },
  { email: 'member04@example.com', inicio: 11.0, fim: 19.0 },
  { email: 'member05@example.com', inicio: 13.0, fim: 22.0 },
  { email: 'member06@example.com', inicio: 6.0, fim: 15.0 }
];

// O e-mail de fallback (usado de madrugada ou se der erro)
const fallbackEmail = 'member02@example.com';

// 3. Descobre quem está online AGORA
let ativos = escala.filter(p => horaAtual >= p.inicio && horaAtual < p.fim).map(p => p.email);

// Se não tiver ninguém online, Henrique é o padrão
if (ativos.length === 0) {
  ativos = [fallbackEmail];
}

// 4. Lógica de Rodízio (Round-Robin) Dinâmico
const mem = $getWorkflowStaticData('global');

if (!mem.ultimo_tvr_email) {
  mem.ultimo_tvr_email = '';
}

let ultimoIndex = ativos.indexOf(mem.ultimo_tvr_email);
let proximoIndex = ultimoIndex + 1;

if (proximoIndex >= ativos.length) {
  proximoIndex = 0;
}

const emailEscolhido = ativos[proximoIndex];
mem.ultimo_tvr_email = emailEscolhido;

// 5. Busca o ID do usuário no ClickUp para fazer a atribuição
const workspaceData = $( 'Buscar Membros da Workspace' ).first().json;
const clickupUsers = workspaceData.team.members;

let userEncontrado = clickupUsers.find(m => m.user.email.toLowerCase() === emailEscolhido.toLowerCase());

// 🛡️ PLANO B (Fallback): Se não achar o e-mail sorteado, passa pro Henrique
if (!userEncontrado) {
  userEncontrado = clickupUsers.find(m => m.user.email.toLowerCase() === fallbackEmail.toLowerCase());
}

// Previne erro fatal se até o fallback falhar
if (userEncontrado) {
    $json.assignee_ids = [ userEncontrado.user.id ];
} else {
    $json.assignee_ids = []; 
}

return { json: $json };

